import React from 'react';
import '../styles/DevNoticeModal.css';

const DevNoticeModal = ({ isOpen, onClose }) => {
  if (!isOpen) return null;
  
  const handleClose = (dontShowAgain) => {
    onClose(dontShowAgain);
  };

  return (
    <div className="modal-overlay">
      <div className="dev-notice-modal">
        <div className="modal-header">
          <div className="warning-icon">
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="24" height="24">
              <path fill="currentColor" d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm0 15c-.83 0-1.5-.67-1.5-1.5S11.17 14 12 14s1.5.67 1.5 1.5S12.83 17 12 17zm1-4h-2V7h2v6z"/>
            </svg>
          </div>
          <h2>Perhatian</h2>
        </div>
        
        <div className="modal-body">
          <p>Website <strong>StockAdvice v1.0</strong> masih dalam tahap pengembangan dan perbaikan.</p>
          
          <p>Beberapa fitur mungkin belum berfungsi dengan sempurna atau masih dalam proses implementasi.</p>
          
          <p>Terima kasih atas pengertian dan kesabaran Anda.</p>
          
          <div className="checkbox-container">
            <input 
              type="checkbox" 
              id="dontShowAgain"
              className="checkbox-input"
            />
            <label htmlFor="dontShowAgain" className="checkbox-label">
              Jangan tampilkan notifikasi ini lagi
            </label>
          </div>
          
          <button 
            className="understand-button"
            onClick={() => {
              const checkbox = document.getElementById('dontShowAgain');
              handleClose(checkbox.checked);
            }}
          >
            Saya Mengerti
          </button>
        </div>
      </div>
    </div>
  );
};

export default DevNoticeModal;
